import{_ as l,a0 as c,w as d,s as p,I as i,x as a,a1 as t,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"10 个例子教你学会 ncat (nc) 命令 | LCTT x X-CMD","titleTemplate":false,"description":"10 个例子教你学会 ncat (nc) 命令 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 个例子教你学会 ncat (nc) 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 个例子教你学会 ncat (nc) 命令 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171206 10 useful ncat (nc) Command Examples for Linux Systems","title":"10 个例子教你学会 ncat (nc) 命令","tag":"201712","desc":""},"relativePath":"201712/20171206 10 useful ncat (nc) Command Examples for Linux Systems.md","filePath":"[post].md"}'),h={name:"201712/20171206 10 useful ncat (nc) Command Examples for Linux Systems.md"};function r(g,s,k,b,u,f){const e=c("Link");return d(),p("div",null,[s[14]||(s[14]=i("h1",{id:"_10-个例子教你学会-ncat-nc-命令",tabindex:"-1"},[a("10 个例子教你学会 ncat (nc) 命令 "),i("a",{class:"header-anchor",href:"#_10-个例子教你学会-ncat-nc-命令","aria-label":"Permalink to “10 个例子教你学会 ncat (nc) 命令”"},"​")],-1)),i("p",null,[t(e,{href:"https://www.linuxtechi.com/wp-content/uploads/2017/12/nc-ncat-command-examples-Linux-Systems.jpg"},{default:n(()=>[...s[0]||(s[0]=[i("img",{src:"https://www.linuxtechi.com/wp-content/uploads/2017/12/nc-ncat-command-examples-Linux-Systems.jpg",alt:"nc-ncat-command-examples-Linux-Systems"},null,-1)])]),_:1})]),s[15]||(s[15]=o(`<p><code>ncat</code> 或者说 <code>nc</code> 是一款功能类似 <code>cat</code> 的工具，但是是用于网络的。它是一款拥有多种功能的 CLI 工具，可以用来在网络上读、写以及重定向数据。 它被设计成可以被脚本或其他程序调用的可靠的后端工具。同时由于它能创建任意所需的连接，因此也是一个很好的网络调试工具。</p><p><code>ncat</code>/<code>nc</code> 既是一个端口扫描工具，也是一款安全工具，还能是一款监测工具，甚至可以做为一个简单的 TCP 代理。 由于有这么多的功能，它被誉为是网络界的瑞士军刀。 这是每个系统管理员都应该知道并且掌握它。</p><p>在大多数 Debian 发行版中，<code>nc</code> 是默认可用的，它会在安装系统的过程中自动被安装。 但是在 CentOS 7 / RHEL 7 的最小化安装中，<code>nc</code> 并不会默认被安装。 你需要用下列命令手工安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# yum install nmap-ncat -y</span></span></code></pre></div><p>系统管理员可以用它来审计系统安全，用它来找出开放的端口然后保护这些端口。 管理员还能用它作为客户端来审计 Web 服务器、telnet 服务器、邮件服务器等， 通过 <code>nc</code> 我们可以控制发送的每个字符，也可以查看对方的回应。</p><p>我们还可以用它捕获客户端发送的数据以此来了解这些客户端是做什么的。</p><p>在本文中，我们会通过 10 个例子来学习如何使用 <code>nc</code> 命令。</p><h3 id="例子-1-监听入站连接" tabindex="-1">例子： 1) 监听入站连接 <a class="header-anchor" href="#例子-1-监听入站连接" aria-label="Permalink to “例子： 1) 监听入站连接”">​</a></h3><p>通过 <code>-l</code> 选项，<code>ncat</code> 可以进入监听模式，使我们可以在指定端口监听入站连接。 完整的命令是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l port_number</span></span></code></pre></div><p>比如，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 8080</span></span></code></pre></div><p>服务器就会开始在 8080 端口监听入站连接。</p><h3 id="例子-2-连接远程系统" tabindex="-1">例子： 2) 连接远程系统 <a class="header-anchor" href="#例子-2-连接远程系统" aria-label="Permalink to “例子： 2) 连接远程系统”">​</a></h3><p>使用下面命令可以用 <code>nc</code> 来连接远程系统，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat IP_address port_number</span></span></code></pre></div><p>让我们来看个例子，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 80</span></span></code></pre></div><p>这会创建一个连接，连接到 IP 为 192.168.1.100 的服务器上的 80 端口，然后我们就可以向服务器发送指令了。 比如我们可以输入下面内容来获取完整的网页内容</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET / HTTP/1.1</span></span></code></pre></div><p>或者获取页面名称，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET / HTTP/1.1</span></span></code></pre></div><p>或者我们可以通过以下方式获得操作系统指纹标识，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HEAD / HTTP/1.1</span></span></code></pre></div><p>这会告诉我们使用的是什么软件来运行这个 web 服务器的。</p><h3 id="例子-3-连接-udp-端口" tabindex="-1">例子： 3) 连接 UDP 端口 <a class="header-anchor" href="#例子-3-连接-udp-端口" aria-label="Permalink to “例子： 3) 连接 UDP 端口”">​</a></h3><p>默认情况下，<code>nc</code> 创建连接时只会连接 TCP 端口。 不过我们可以使用 <code>-u</code> 选项来连接到 UDP 端口，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l -u 1234</span></span></code></pre></div><p>现在我们的系统会开始监听 UDP 的 1234 端口，我们可以使用下面的 <code>netstat</code> 命令来验证这一点，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ netstat -tunlp | grep 1234</span></span>
<span class="line"><span>udp           0          0 0.0.0.0:1234                 0.0.0.0:*               17341/nc</span></span>
<span class="line"><span>udp6          0          0 :::1234                      :::*                    17341/nc</span></span></code></pre></div><p>假设我们想发送或者说测试某个远程主机 UDP 端口的连通性，我们可以使用下面命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -v -u {host-ip} {udp-port}</span></span></code></pre></div><p>比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@localhost ~]# ncat -v -u 192.168.105.150 53</span></span>
<span class="line"><span>Ncat: Version 6.40 ( http://nmap.org/ncat )</span></span>
<span class="line"><span>Ncat: Connected to 192.168.105.150:53。</span></span></code></pre></div><h3 id="例子-4-将-nc-作为聊天工具" tabindex="-1">例子： 4) 将 <code>nc</code> 作为聊天工具 <a class="header-anchor" href="#例子-4-将-nc-作为聊天工具" aria-label="Permalink to “例子： 4) 将 nc 作为聊天工具”">​</a></h3><p><code>nc</code> 也可以作为聊天工具来用，我们可以配置服务器监听某个端口，然后从远程主机上连接到服务器的这个端口，就可以开始发送消息了。 在服务器这端运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 8080</span></span></code></pre></div><p>在远程客户端主机上运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 8080</span></span></code></pre></div><p>之后开始发送消息，这些消息会在服务器终端上显示出来。</p><h3 id="例子-5-将-nc-作为代理" tabindex="-1">例子： 5) 将 <code>nc</code> 作为代理 <a class="header-anchor" href="#例子-5-将-nc-作为代理" aria-label="Permalink to “例子： 5) 将 nc 作为代理”">​</a></h3><p><code>nc</code> 也可以用来做代理。比如下面这个例子，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 8080 | ncat 192.168.1.200 80</span></span></code></pre></div><p>所有发往我们服务器 8080 端口的连接都会自动转发到 192.168.1.200 上的 80 端口。 不过由于我们使用了管道，数据只能被单向传输。 要同时能够接受返回的数据，我们需要创建一个双向管道。 使用下面命令可以做到这点:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkfifo 2way</span></span>
<span class="line"><span>$ ncat -l 8080 0&lt;2way | ncat 192.168.1.200 80 1&gt;2way</span></span></code></pre></div><p>现在你可以通过 <code>nc</code> 代理来收发数据了。</p><h3 id="例子-6-使用-nc-拷贝文件" tabindex="-1">例子： 6) 使用 <code>nc</code> 拷贝文件 <a class="header-anchor" href="#例子-6-使用-nc-拷贝文件" aria-label="Permalink to “例子： 6) 使用 nc 拷贝文件”">​</a></h3><p><code>nc</code> 还能用来在系统间拷贝文件，虽然这么做并不推荐，因为绝大多数系统默认都安装了 <code>ssh</code>/<code>scp</code>。 不过如果你恰好遇见个没有 <code>ssh</code>/<code>scp</code> 的系统的话， 你可以用 <code>nc</code> 来作最后的努力。</p><p>在要接受数据的机器上启动 <code>nc</code> 并让它进入监听模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l  8080 &gt; file.txt</span></span></code></pre></div><p>现在去要被拷贝数据的机器上运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 8080 --send-only &lt; data.txt</span></span></code></pre></div><p>这里，<code>data.txt</code> 是要发送的文件。 <code>-–send-only</code> 选项会在文件拷贝完后立即关闭连接。 如果不加该选项， 我们需要手工按下 <code>ctrl+c</code> 来关闭连接。</p><p>我们也可以用这种方法拷贝整个磁盘分区，不过请一定要小心。</p><h3 id="例子-7-通过-nc-创建后门" tabindex="-1">例子： 7) 通过 <code>nc</code> 创建后门 <a class="header-anchor" href="#例子-7-通过-nc-创建后门" aria-label="Permalink to “例子： 7) 通过 nc 创建后门”">​</a></h3><p><code>nc</code> 命令还可以用来在系统中创建后门，并且这种技术也确实被黑客大量使用。 为了保护我们的系统，我们需要知道它是怎么做的。 创建后门的命令为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l 10000 -e /bin/bash</span></span></code></pre></div><p><code>-e</code> 标志将一个 bash 与端口 10000 相连。现在客户端只要连接到服务器上的 10000 端口就能通过 bash 获取我们系统的完整访问权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat 192.168.1.100 10000</span></span></code></pre></div><h3 id="例子-8-通过-nc-进行端口转发" tabindex="-1">例子： 8) 通过 <code>nc</code> 进行端口转发 <a class="header-anchor" href="#例子-8-通过-nc-进行端口转发" aria-label="Permalink to “例子： 8) 通过 nc 进行端口转发”">​</a></h3><p>我们通过选项 <code>-c</code> 来用 <code>nc</code> 进行端口转发，实现端口转发的语法为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -u -l  80 -c  &#39;ncat -u -l 8080&#39;</span></span></code></pre></div><p>这样，所有连接到 80 端口的连接都会转发到 8080 端口。</p><h3 id="例子-9-设置连接超时" tabindex="-1">例子： 9) 设置连接超时 <a class="header-anchor" href="#例子-9-设置连接超时" aria-label="Permalink to “例子： 9) 设置连接超时”">​</a></h3><p><code>nc</code> 的监听模式会一直运行，直到手工终止。 不过我们可以通过选项 <code>-w</code> 设置超时时间:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -w 10 192.168.1.100 8080</span></span></code></pre></div><p>这回导致连接 10 秒后终止，不过这个选项只能用于客户端而不是服务端。</p><h3 id="例子-10-使用-k-选项强制-nc-待命" tabindex="-1">例子： 10) 使用 <code>-k</code> 选项强制 <code>nc</code> 待命 <a class="header-anchor" href="#例子-10-使用-k-选项强制-nc-待命" aria-label="Permalink to “例子： 10) 使用 -k 选项强制 nc 待命”">​</a></h3><p>当客户端从服务端断开连接后，过一段时间服务端也会停止监听。 但通过选项 <code>-k</code> 我们可以强制服务器保持连接并继续监听端口。 命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncat -l -k 8080</span></span></code></pre></div><p>现在即使来自客户端的连接断了也依然会处于待命状态。</p><p>自此我们的教程就完了，如有疑问，请在下方留言。</p><hr>`,73)),i("p",null,[s[2]||(s[2]=a("via: ",-1)),t(e,{href:"https://www.linuxtechi.com/nc-ncat-command-examples-linux-systems/"},{default:n(()=>[...s[1]||(s[1]=[a("https://www.linuxtechi.com/nc-ncat-command-examples-linux-systems/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),t(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[3]||(s[3]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 译者：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[10]||(s[10]=[a("Linux中国",-1)])]),_:1}),s[13]||(s[13]=a(" 荣誉推出",-1))])])}const C=l(h,[["render",r]]);export{x as __pageData,C as default};
